BEGIN;
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;
CREATE TABLE d_booking_policy (id VARCHAR(100) PRIMARY KEY, "maxHours" INTEGER NOT NULL DEFAULT 4 CHECK ("maxHours" BETWEEN 1 AND 24));
CREATE TABLE d_opening_rules ("roomId" VARCHAR(100) NOT NULL REFERENCES d_rooms(id) ON DELETE RESTRICT ON UPDATE CASCADE, weekday INTEGER NOT NULL CHECK (weekday BETWEEN 0 AND 6), "opensHour" INTEGER NOT NULL CHECK ("opensHour" BETWEEN 0 AND 23), "closesHour" INTEGER NOT NULL CHECK ("closesHour" BETWEEN 1 AND 24), PRIMARY KEY ("roomId",weekday,"opensHour"), CHECK ("opensHour" < "closesHour"));
CREATE TABLE m1_bookings (id UUID PRIMARY KEY, "roomId" VARCHAR(100) NOT NULL REFERENCES d_rooms(id) ON DELETE RESTRICT ON UPDATE CASCADE, "seatId" VARCHAR(100) NOT NULL REFERENCES d_seats(id) ON DELETE RESTRICT ON UPDATE CASCADE, "userId" VARCHAR(100) NOT NULL REFERENCES d_users(id) ON DELETE RESTRICT ON UPDATE CASCADE, "startsAt" TIMESTAMPTZ(3) NOT NULL, "endsAt" TIMESTAMPTZ(3) NOT NULL, status VARCHAR(30) NOT NULL CHECK (status IN ('BOOKED','CANCELLED','CHECKED_IN','COMPLETED','NO_SHOW')), "cancelReason" VARCHAR(1000), "cancelledAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK ("startsAt" < "endsAt"));
CREATE INDEX "m1_bookings_roomId_startsAt_endsAt_idx" ON m1_bookings ("roomId","startsAt","endsAt");
CREATE INDEX "m1_bookings_userId_id_idx" ON m1_bookings ("userId",id);
ALTER TABLE m1_bookings ADD CONSTRAINT m1_no_seat_overlap EXCLUDE USING gist ("seatId" WITH =, tstzrange("startsAt","endsAt",'[)') WITH &&) WHERE (status IN ('BOOKED','CHECKED_IN'));
CREATE TABLE m1_write_receipts (id VARCHAR(200) PRIMARY KEY, fingerprint CHAR(64) NOT NULL, result JSONB NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE m1_resource_effects ("sourceModule" VARCHAR(10) NOT NULL CHECK ("sourceModule" IN ('M2','M3')), "sourceId" VARCHAR(100) NOT NULL, "roomId" VARCHAR(100) REFERENCES d_rooms(id) ON DELETE RESTRICT ON UPDATE CASCADE, "startsAt" TIMESTAMPTZ(3), "endsAt" TIMESTAMPTZ(3), state VARCHAR(20) NOT NULL CHECK (state IN ('ACTIVE','RELEASED')), revision INTEGER NOT NULL CHECK (revision >= 1), "operationId" UUID NOT NULL, "actorId" VARCHAR(100) NOT NULL, reason VARCHAR(1000) NOT NULL, "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("sourceModule","sourceId"), CHECK (state <> 'ACTIVE' OR ("roomId" IS NOT NULL AND "startsAt" IS NOT NULL)), CHECK ("endsAt" IS NULL OR "startsAt" < "endsAt"));
CREATE INDEX "m1_resource_effects_roomId_state_startsAt_endsAt_idx" ON m1_resource_effects ("roomId",state,"startsAt","endsAt");
CREATE TABLE m1_commands ("operationId" UUID PRIMARY KEY, fingerprint CHAR(64) NOT NULL, "sourceModule" VARCHAR(10) NOT NULL, "sourceId" VARCHAR(100) NOT NULL, status INTEGER NOT NULL, response JSONB NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "m1_commands_sourceModule_sourceId_idx" ON m1_commands ("sourceModule","sourceId");
COMMIT;
